{
  "title": "Discussion about living and working abroad",
  "topics": [
    {
      "id": "expat-slovakia",
      "title": "People living or planning to live in Slovakia",
      "claims": [
        {
          "text": "Some members live in Bratislava or elsewhere in Slovakia",
          "evidence": [1, 43]
        },
        {
          "text": "The user P1 has been in Slovakia for almost a year",
          "evidence": [43]
        },
        {
          "text": "There are acquaintances of the group in Austria and Poland",
          "evidence": [3, 12]
        }
      ]
    },
    {
      "id": "job-search-abroad",
      "title": "Finding jobs abroad",
      "claims": [
        {
          "text": "LinkedIn is recommended for job hunting",
          "evidence": [18]
        },
        {
          "text": "About 100 applications yielded only 3 interviews for P3",
          "evidence": [21]
        },
        {
          "text": "Local language requirement appears in most job postings (about 95%)",
          "evidence": [26]
        },
        {
          "text": "Higher education rarely matters for getting interviews",
          "evidence": [32]
        },
        {
          "text": "Salary expectations in Europe are generally higher than in Ukraine, but many ignore it",
          "evidence": [35]
        },
        {
          "text": "Candidate accepted a low salary because they needed any job urgently",
          "evidence": [37, 40, 41]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language needs for work and daily life",
      "claims": [
        {
          "text": "German is commonly spoken at work in Austria, but English is also used",
          "evidence": [14, 16]
        },
        {
          "text": "Employers often request B2 level German, sometimes B1, and certificates are not always required",
          "evidence": [46]
        },
        {
          "text": "The speaker feels uncomfortable speaking German in everyday situations",
          "evidence": [47]
        },
        {
          "text": "In Slovakia the surrounding community speaks Ukrainian, while work language is English",
          "evidence": [44, 45]
        }
      ]
    },
    {
      "id": "salary-info",
      "title": "Salary discussions",
      "claims": [
        {
          "text": "Salary for the speaker's position was higher than a minimum wage but still low compared to expectations",
          "evidence": [37]
        },
        {
          "text": "In Europe developers tend to earn more than in Ukraine",
          "evidence": [35]
        }
      ]
    },
    {
      "id": "future-plans",
      "title": "Future relocation considerations",
      "claims": [
        {
          "text": "One participant is considering attending a Warsaw tech event (wawtech.io/summer)",
          "evidence": [59]
        },
        {
          "text": "A partner living in Austria for over 10 years is pessimistic about the country's future",
          "evidence": [60]
        },
        {
          "text": "The same participant views Austria as the best choice among European countries",
          "evidence": [60]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Should the group focus on learning German to improve job prospects?",
      "evidence": [46, 47]
    },
    {
      "text": "Is moving to Warsaw for the tech event a viable next step?",
      "evidence": [59]
    }
  ]
